<?php declare(strict_types=1);
namespace App\Results;
use App\Database;
final class TrackingStore {
 public static function settings():array{ $p=Database::pdo(); self::ensure($p); $r=$p->query("SELECT * FROM result_tracking_settings WHERE id=1")->fetch(\PDO::FETCH_ASSOC); return $r?:['enabled'=>0,'scope'=>'all','check_results'=>0,'daily_report'=>0,'report_time'=>'00:00:00','report_chat'=>'','test_mode'=>1];}
 public static function enabledForRule(array $rule):bool{$s=self::settings();if(empty($s['enabled']))return false;if(($s['scope']??'all')==='all')return true;$p=Database::pdo();$q=$p->prepare("SELECT enabled FROM result_tracking_rules WHERE rule_id=?");$q->execute([(int)($rule['id']??0)]);return (bool)$q->fetchColumn();}
 public static function register(array $bet,array $ctx):void{$p=Database::pdo();self::ensure($p);$q=$p->prepare("INSERT IGNORE INTO result_tracking_bets(rule_id,source_chat,destination_chat,source_message_id,home_team,away_team,market,side,line,odds,stake_units,status,placed_at,raw_tip) VALUES(?,?,?,?,?,?,?,?,?,?,10,'PENDING',NOW(),?)");$q->execute([(int)$ctx['rule_id'],(string)$ctx['source_chat'],(string)$ctx['destination_chat'],(int)$ctx['message_id'],$bet['home']??null,$bet['away']??null,(string)$bet['market'],(string)$bet['side'],$bet['line'],(float)$bet['odds'],mb_substr((string)($ctx['raw_tip']??''),0,12000)]);}
 public static function pending():array{$p=Database::pdo();self::ensure($p);return $p->query("SELECT * FROM result_tracking_bets WHERE status='PENDING' AND fixture_id IS NOT NULL ORDER BY id LIMIT 50")->fetchAll(\PDO::FETCH_ASSOC);}
 public static function settle(int $id,array $result,array $details):void{$p=Database::pdo();$q=$p->prepare("UPDATE result_tracking_bets SET status=?,profit_units=?,settled_at=NOW(),settlement_details=? WHERE id=? AND status='PENDING'");$q->execute([$result['status'],$result['profit_units'],json_encode($details,JSON_UNESCAPED_UNICODE),$id]);}
 public static function report(string $date):array{$p=Database::pdo();self::ensure($p);$q=$p->prepare("SELECT COUNT(*) total,SUM(status='GREEN') greens,SUM(status='RED') reds,SUM(status='VOID') voids,SUM(status='HALF_GREEN') half_greens,SUM(status='HALF_RED') half_reds,SUM(status IN ('PENDING','PENDING_REVIEW')) pending,COALESCE(SUM(profit_units),0) profit,COALESCE(AVG(odds),0) avg_odds FROM result_tracking_bets WHERE DATE(placed_at)=?");$q->execute([$date]);return $q->fetch(\PDO::FETCH_ASSOC)?:[];}
 public static function markReport(string $date):bool{$p=Database::pdo();self::ensure($p);$q=$p->prepare("INSERT IGNORE INTO result_tracking_daily_reports(report_date) VALUES(?)");$q->execute([$date]);return $q->rowCount()===1;}
 private static function ensure(\PDO $p):void{$p->exec("CREATE TABLE IF NOT EXISTS result_tracking_settings(id TINYINT PRIMARY KEY,enabled TINYINT NOT NULL DEFAULT 0,scope VARCHAR(16) NOT NULL DEFAULT 'all',check_results TINYINT NOT NULL DEFAULT 0,daily_report TINYINT NOT NULL DEFAULT 0,report_time TIME NOT NULL DEFAULT '00:00:00',report_chat VARCHAR(255) NOT NULL DEFAULT '',test_mode TINYINT NOT NULL DEFAULT 1,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP)");$p->exec("INSERT IGNORE INTO result_tracking_settings(id) VALUES(1)");$p->exec("CREATE TABLE IF NOT EXISTS result_tracking_rules(rule_id BIGINT PRIMARY KEY,enabled TINYINT NOT NULL DEFAULT 0)");}
}
